const urls=new Set();
const items=[];
// Расширенный список: оригинальные + реально найденные Serper
const allowedDomains=['zakupki.gov.ru','rts-tender.ru','b2b-center.ru','tenderland.ru','tender.pro','roseltorg.ru','sberbank-ast.ru','rostender.info','tektorg.ru','bicotender.ru','expertcentre.org'];
// Ключевые слова тендерной тематики в URL
const tenderKeywords=['tender','zakupk','закупк','госзаказ','торги','лотов'];

const inputItems=$input.all()||[];
for(const item of inputItems){
  if(!item||!item.json)continue;
  const j=item.json;
  const organic=j.organic||[];
  const results=j.results||[];
  for(const o of organic){
    const link=o.link;
    if(!link||urls.has(link))continue;
    const isTenderDomain=allowedDomains.some(d=>link.includes(d));
    const hasTenderKeyword=tenderKeywords.some(k=>link.toLowerCase().includes(k));
    if(isTenderDomain||hasTenderKeyword){
      urls.add(link);
      items.push({json:{url:link,title:o.title||'',snippet:o.snippet||''}});
    }
  }
  for(const r of results){
    const link=r.url;
    if(!link||urls.has(link))continue;
    const isTenderDomain=allowedDomains.some(d=>link.includes(d));
    const hasTenderKeyword=tenderKeywords.some(k=>link.toLowerCase().includes(k));
    if(isTenderDomain||hasTenderKeyword){
      urls.add(link);
      items.push({json:{url:link,title:r.title||'',snippet:r.content||''}});
    }
  }
}
return items.slice(0,10).length>0?items.slice(0,10):[{json:{skip:true}}];

const item = $input.first();
if (!item || !item.json) return [{ json: { skip: true } }];

const fcRaw = item.json;
const cfg = $('Config').first().json;

// Восстанавливаем контекст из Loop Tenders
let ctx = {};
try {
  const loopItems = $items("Loop Tenders", 0, $runIndex);
  if (loopItems && loopItems.length > 0) ctx = loopItems[0].json || {};
} catch(e) {
  try { ctx = $('Loop Tenders').item?.json || {}; } catch(e2) {}
}

const sourceUrl = ctx.url || '';
const sourceTitle = ctx.title || '';

// Автоопределение структуры Firecrawl
const fc = fcRaw.firecrawlResult || (fcRaw.success !== undefined ? fcRaw : {});
const fcData = (fc.data || fc);
const md = fcData.markdown || fcData.content || fcRaw.markdown || '';
const metadata = fcData.metadata || {};

const budgetM = md.match(/([\d\s.,]+)\s*(?:руб|₽|тыс|млн)/i);
let budget = 0;
if (budgetM && budgetM[1]) {
  const num = parseInt(budgetM[1].replace(/\D/g, ''), 10) || 0;
  if (/млн/i.test(budgetM[0])) budget = num * 1000000;
  else if (/тыс/i.test(budgetM[0])) budget = num * 1000;
  else budget = num;
}

const deadlineM = md.match(/(?:до|окончани[ея]|deadline)[\s\S]{0,50}?(\d{1,2}[\.\/-]\d{1,2}[\.\/-]\d{2,4})/i);
const numberM = md.match(/№\s*([А-ЯA-Z0-9\-\/]{5,})/i);
const titleM = md.match(/^#\s+(.+)$/m);

let hostname = 'unknown';
try {
  const hostMatch = sourceUrl.match(/^(?:https?:\/\/)?(?:www\.)?([^\/]+)/i);
  if (hostMatch && hostMatch[1]) hostname = hostMatch[1];
} catch(e) {}

return [{
  json: {
    tender_id: 'tnd_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 10),
    job_id: cfg.job_id,
    platform: hostname,
    url: sourceUrl,
    title: titleM ? titleM[1] : (metadata.title || sourceTitle),
    budget: budget,
    deadline: deadlineM ? deadlineM[1] : null,
    tender_number: numberM ? numberM[1] : null,
    raw_content: md.slice(0, 3000)
  }
}];

const item = $input.first();
if (!item || !item.json) return [{ json: { skip: true } }];

const raw = item.json.choices?.[0]?.message?.content || '{}';
let p = {};
try {
  const cleanRaw = raw.replace(/```json/gi, '').replace(/```/g, '').trim();
  p = JSON.parse(cleanRaw);
} catch(e) {
  p = {};
}

// Получаем текущий тендер из Parse Tender через Loop Tenders
let tender = {};
try {
  const loopItems = $items("Loop Tenders", 0, $runIndex);
  if (loopItems && loopItems.length > 0) tender = loopItems[0].json || {};
} catch(e) {
  try { tender = $('Loop Tenders').item?.json || {}; } catch(e2) {}
}
// Если через Loop не получилось — пробуем Parse Tender напрямую
if (!tender.url) {
  try { tender = $('Parse Tender').first().json || {}; } catch(e) {}
}

const reqs = Array.isArray(p.required_prerequisites) ? p.required_prerequisites.join('; ') : (p.required_prerequisites || '');

return [{
  json: {
    ...tender,
    relevance_score: Number(p.relevance_score) || 0,
    matched_service: p.matched_service || '',
    win_probability: Number(p.win_probability) || 0,
    required_prerequisites: reqs,
    summary: p.summary_ru || '',
    total_score: Number(p.relevance_score) || 0,
    scraped_at: new Date().toISOString(),
    entity_type: 'tender'
  }
}];
